-- GENERATED by `wfj generate` from data/gossip/gossip-d0.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["d001a1805997a24a"] = { "Accesso ai dati consentito. Buona giornata!\n\n01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011", "." },
  ["d00d76f99da6c0e4"] = { "Ahimè... mi spiace dirtelo, ma al momento non posso leggerti la fortuna, perché te l'ho letta di recente.\n\nTorna da me qualche ora dopo la tua prima lettura. Le forze del Fato si saranno ricalibrate a dovere e potrò vedere nel tuo futuro.", "." },
  ["d00e32bd7ae55e77"] = { "Salute... Windshaper.\r\n\nChi si definisce membro dei Windshapers trova poca causa comune con la maggior parte dei membri dell'High Order, come di certo saprai. Fuori dalla relativa armonia del ⟦Thendal Grove=Boschetto di Thendal⟧, potresti scoprire che queste divisioni sono davvero profonde e che la rivalità, in alcuni casi, può sfociare in aperta violenza.\r\n\nNon dirò altro in proposito, se non che dovresti badare agli affari tuoi e non intralciare gli scopi dell'High Order una volta lasciato il boschetto. Probabilmente è l'unico avvertimento che riceverai.", "." },
  ["d010dcc39319e546"] = { "Ehi, che vuoi?", "." },
  ["d011ba36558fff37"] = { "Ce l'hai fatta! Evviva!\n\nMetzen è tornato in volo alle stalle di Babbo Inverno (sì, Metzen sa volare davvero) poco fa! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Festa del Grande Inverno e anche la Masseria Buongusto. Grazie, {name}.\n\nSenti... per quello che hai fatto, voglio che tu abbia questo. È qualcosa di MOLTO speciale; se hai una cavalcatura, credo che ti divertirà parecchio. Buon Grande Inverno!", "." },
  ["d01b24f1447d91de"] = { "Onori la mia specie, {name}. Abbatti i nemici di Kalimdor! Mostra loro cosa significa deturpare la terra dell'eterna luce stellare.\n\nTi sei <guadagnato/guadagnata> un altro potenziamento. Dammi il tuo anello con sigillo, così che io possa rafforzarne il potere.", "." },
  ["d01de45166da4d03"] = { "Hai tanta fretta di morire? Sarò felice di accontentarti...", "." },
  ["d029618373c7816a"] = { "Narain, mi serve un altro kit speciale.", "." },
  ["d02a50fc0c9d6c3a"] = { "Mi interessa l'addestramento da sarto.", "." },
  ["d0323cfc721454ac"] = { "Hai trovato qualcosa? Non ci spero molto.", "." },
  ["d035977b8bff237b"] = { "Non posso insegnare a un tauren a cavalcare un raptor.", "." },
  ["d03ea24d98759581"] = { "%s getta sul tavolo la lettera di Anton.", "." },
  ["d0410525ee565060"] = { "Puoi trovare l'istruttore di cucina in una casetta all'estremità nord del paese.", "." },
  ["d046cc7d2b696be5"] = { "Salve, {class}, gentile da parte tua farti vedere. Sarò breve: stiamo raccogliendo rifornimenti per lo sforzo bellico di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Non vorremmo più vittime del necessario, vero? Ho la responsabilità di coordinare la raccolta di $2086w bende di telamagica. Finora ne abbiamo raccolte $2085w. Vuoi dare una mano?", "." },
  ["d0494aa268658121"] = { "Forse esiste un modo?", "." },
  ["d050b10c220eecfc"] = { "Un'altra bella giornata sulla nostra splendida isola.", "." },
  ["d0539fa5b1c23757"] = { "%s chiama in suo aiuto un ⟦Blackhand Dreadweaver=Mistico del Terrore Manonera⟧!", "." },
  ["d054b9b435ca03d0"] = { "Venite, fratelli.", "." },
  ["d055916d277be635"] = { "Ho meno di un terzo dei rifornimenti necessari per passare alle unità veterane.", "." },
  ["d05a516c75398c9f"] = { "La Frostwolf Relief Hut si trova nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, a sud delle Torri dei Lupi Bianchi.\n\nÈ sotto il controllo dell'⟦Horde=Orda⟧.", "." },
  ["d05af143b9fc931d"] = { "Perché mi disturbi, recluta? Se vuoi parlare con altri sciocchi dagli occhi sgranati, prova la locanda sul lato nord del paese. Le reclute che si radunano lì tendono ad avere il cervello liscio come le loro teste appena rasate.\r\n\nAh, e rasati quella testa. L'unica cosa che il signore del vento detesta più delle reclute chiacchierone sono le reclute chiacchierone con una chioma folta.\r\n\nOra sparisci dalla mia vista.", "." },
  ["d0636a87a67230fa"] = { "Salute, Astarii. Ho bisogno di addestramento.", "." },
  ["d06e06d73c573bae"] = { "Questa statuetta deve avere uno scomparto segreto...", "." },
  ["d06ec4b1b786bf60"] = { "Qui sei sempre <benvenuto/benvenuta>, {name}. Grazie per le risate, e non preoccuparti per Daryl: se l'era cercata!", "." },
  ["d07d6bc7930a71a9"] = { "Buona fortuna, giovane <cacciatore/cacciatrice>.", "." },
  ["d07d90a8971a69c8"] = { "Puoi parlare liberamente, Neeru...", "." },
  ["d081eae159b11b01"] = { "Serge, ho perso la cura per il ⟦Touch of Zanzil=Tocco di Zanzil⟧! AIUTO!", "." },
  ["d08a4be7d3ccf483"] = { "Ah, eccoti. Mi avevano detto di aspettarmi aiuto, quindi ascolta bene. La situazione è questa: mi è stato affidato il compito di raccogliere $2055w fiori di loto purpureo in vista della guerra imminente ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Finora ne abbiamo $2054w.\n\nAndare sul campo a raccogliere i fiori spetterà a te e a quelli come te. Io devo restare qui per assicurarmi che vengano conservati bene e per trovare nuovi modi creativi di usarli contro i silitidi e qualunque altra cosa ci aspetti laggiù.", "." },
  ["d08a5fa50787fb41"] = { "%s esamina il ⟦Moss-twined Heart=Cuore Avvolto dal Muschio⟧...", "." },
  ["d08aa0ad2aed6c75"] = { "Segnalata molta attività di gnoll nella ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧ e nella ⟦Jangolode Mine=Miniera Venacava⟧.", "." },
  ["d08ad249ba71df22"] = { "Possiamo fare una pausa? I piedi mi stanno uccidendo, e quelle... quelle cose laggiù mi mettono i brividi.", "." },
  ["d08fdd677f65bdc4"] = { "Più aspetti, meno futuro avrai da farti predire.", "." },
  ["d090ef239394073a"] = { "Ti do il benvenuto al Blue Recluse, dove gli appassionati di magia si riuniscono per scaricare la tensione. Non in senso letterale, s'intende. Cosa ti porto, <signore/signora>?", "." },
  ["d09f0b82e3d7a1c4"] = { "Ti serve la Kodohide Leatherworkers. La trovi a metà del Varcolargo.", "." },
  ["d0a062b8151c629d"] = { "%s sfoglia freneticamente le pagine di un grosso tomo.", "." },
  ["d0bcc91ef5a6932c"] = { "Grazie ancora per aver aiutato Hilary, <signore/signorina>! Da grande voglio diventare come te, un vero eroe!", "." },
  ["d0bda16ed9c75477"] = { "No! Amico mio... cos'è successo? È tutta colpa mia...", "." },
  ["d0bf1c0b69783923"] = { "Non troverai scuoiatori qui fuori a Dun Morogh, <ragazzo/ragazza>: si trovano per lo più a ⟦Ironforge=Forgiardente⟧, se vuoi farti addestrare.", "." },
  ["d0c14264c4924743"] = { "Quindi la serie di magie si propagherebbe in una reazione a catena di energie a carica positiva.", "." },
  ["d0cd46daf912d3f0"] = { "Come posso liberarti?", "." },
  ["d0d094899f0e05fe"] = { "Lo farò.", "." },
  ["d0d42c4ce72e9b5b"] = { "Attenzione! Mi stanno attaccando!", "." },
  ["d0da57d57454a87e"] = { "Tutto qui?", "." },
  ["d0dbcb58c9022c6f"] = { "⟦Tower Point=Torre Granguardia⟧ è stata distrutta dall'⟦Alliance=Alleanza⟧!", "." },
  ["d0e503bd869d015f"] = { "Mostrate il vostro coraggio, uomini e donne di Azeroth! Respingete gli invasori Qiraji!", "." },
  ["d0e5fa584a294b0a"] = { "Attenzione, {name}! Guarda a ovest!", "." },
  ["d0fb8845b2cbd889"] = { "Spero di aprire presto una bottega tutta mia! Nel frattempo, vuoi comprare qualcosa?\r\n\nOgni moneta mi aiuta a finanziare il mio sogno!", "." },
  ["d0fb88a1cf394f7c"] = { "So che stavolta funzionerà...", "." },
})
